/* PR 4A CANDIDATE: disposable verification only; no automatic installation/activation. */
SET NOCOUNT ON; SET XACT_ABORT ON; SET QUOTED_IDENTIFIER ON; SET ANSI_NULLS ON;
IF USER_NAME()<>'dbo' OR @@TRANCOUNT<>0 OR SESSION_CONTEXT(N'ShaleClientId') IS NOT NULL OR SESSION_CONTEXT(N'PrincipalUserId') IS NOT NULL
 THROW 59400,'Fresh unscoped dbo lease required.',1;
BEGIN TRY BEGIN TRANSACTION;
DECLARE @C4aLock int;
EXEC @C4aLock=sys.sp_getapplock @Resource=N'AiSchemaV1',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=3000;
IF @C4aLock<0 OR NOT EXISTS(SELECT 1 FROM dbo.AiProductCapability WHERE Id=1 AND Enabled=0)
 THROW 59400,'Exclusive schema lock and capability OFF required.',1;
DECLARE @C4aPredecessors0 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aPredecessors0;
DECLARE @C4aPredecessors1 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aPredecessors1;
DECLARE @C4aObjects table(Name sysname PRIMARY KEY); INSERT @C4aObjects VALUES (N'AiCimdFamilyV1'),(N'AiCimdCredentialV1'),(N'AiCimdInvocationV1'),(N'AiCimdProofControlV1'),(N'AiCimdProofReceiptV1'),(N'AiCimdDataLocateAccessOwnerV1'),(N'AiCimdDataLoadAuthorityV1'),(N'AiCimdDataAuthenticateV1'),(N'AiCimdDataAppendAccessV1'),(N'AiCimdDataAdmitV1'),(N'AiCimdDataSearchCasesV1'),(N'AiCimdDataGetCaseOverviewV1'),(N'AiCimdDataFinishCaseQuotaV1'),(N'AiCimdDataAuthorizeCaseHandoffV1'),(N'AiCimdDataRecordCaseFailureV1'),(N'AiCimdDataImmutableInvocation'),(N'AiCimdImmutableFamilyV1'),(N'AiCimdImmutableCredentialV1'),(N'AiCimdLifecycle_CredentialV1'),(N'AiCimdRevokeFamilyV1'),(N'AiCimdImmutableReceiptV1');
IF EXISTS(SELECT 1 FROM sys.objects WHERE schema_id=SCHEMA_ID('dbo') AND name IN(SELECT Name FROM @C4aObjects)) OR EXISTS(SELECT 1 FROM sys.database_principals WHERE name IN('AiCimdCaseRuntimeV1','AiCimdLifecycleV1')) THROW 59400,'CIMD proof objects already present; never overwrite.',1;
DECLARE @C4aOldState nvarchar(max)=(SELECT class,major_id,minor_id,name,CONVERT(varchar(max),CONVERT(varbinary(max),value),2) AS ReceiptValue FROM sys.extended_properties WHERE name LIKE 'Shale.%' AND NOT(class=1 AND OBJECT_NAME(major_id) IN(SELECT Name FROM @C4aObjects)) ORDER BY class,major_id,minor_id,name FOR XML PATH('r'),TYPE).value('.','nvarchar(max)');
SET @C4aOldState=@C4aOldState+(SELECT CONCAT(Id,Issuer,Resource,Contract,JavaTimeZone,SqlTimeZone) AS [text()] FROM dbo.AiCaseDataDeployment ORDER BY Id FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
DECLARE @C4aBefore binary(32)=HASHBYTES('SHA2_256',@C4aOldState);
DECLARE @C4aSaved binary(32)=@C4aBefore;
/* PR 4A immutable exchange receipt. No issuer/insert EXECUTE is granted in this increment. */
CREATE TABLE dbo.AiCimdFamilyV1(
 ShaleClientId int NOT NULL, SessionId uniqueidentifier NOT NULL, IntegrationId uniqueidentifier NOT NULL,
 GrantId uniqueidentifier NOT NULL, UserId int NOT NULL,
 TransactionId uniqueidentifier NOT NULL UNIQUE, WebSessionId uniqueidentifier NOT NULL,
 ApplicationId uniqueidentifier NOT NULL, ApplicationRevision bigint NOT NULL,
 ApprovalId uniqueidentifier NOT NULL, ApprovalVersion binary(8) NOT NULL,
 MetadataDigest binary(32) NOT NULL,
 ExternalClientId nvarchar(2048) COLLATE Latin1_General_100_BIN2 NOT NULL,
 ClientId varchar(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
 Issuer nvarchar(256) COLLATE Latin1_General_100_BIN2 NOT NULL,
 Resource nvarchar(256) COLLATE Latin1_General_100_BIN2 NOT NULL,
 CredentialId uniqueidentifier NULL, AuthMethod varchar(16) COLLATE Latin1_General_100_BIN2 NOT NULL,
 RedirectUri nvarchar(2048) COLLATE Latin1_General_100_BIN2 NOT NULL,
 Challenge varchar(43) COLLATE Latin1_General_100_BIN2 NOT NULL,
 CodeHash binary(32) NOT NULL UNIQUE, CodeIssuedAt datetime2(7) NOT NULL, CodeExpiresAt datetime2(7) NOT NULL,
 ConsumedAt datetime2(7) NOT NULL, DeniedAt datetime2(7) NULL,
 CONSTRAINT PK_AiCimdFamilyV1 PRIMARY KEY(ShaleClientId,SessionId),
 CONSTRAINT UQ_AiCimdFamilyV1_Owner UNIQUE(ShaleClientId,SessionId,GrantId,IntegrationId,UserId),
 CONSTRAINT FK_AiCimdFamilyV1_Session FOREIGN KEY(ShaleClientId,SessionId,GrantId,IntegrationId,UserId)
 REFERENCES dbo.AiDelegatedSession(ShaleClientId,SessionId,GrantId,IntegrationId,UserId),
 CONSTRAINT FK_AiCimdFamilyV1_Approval FOREIGN KEY(ShaleClientId,ApprovalId) REFERENCES dbo.AiTenantApplicationApproval(ShaleClientId,ApprovalId),
 CONSTRAINT FK_AiCimdFamilyV1_Revision FOREIGN KEY(ApplicationId,ApplicationRevision) REFERENCES dbo.AiExternalApplicationRevision(ApplicationId,Revision),
 CONSTRAINT FK_AiCimdFamilyV1_Web FOREIGN KEY(WebSessionId) REFERENCES dbo.UserSessions(SessionId),
 CONSTRAINT CK_AiCimdFamilyV1_Method CHECK((AuthMethod='none' AND DATALENGTH(AuthMethod)=4 AND CredentialId IS NULL) OR (AuthMethod='private_key_jwt' AND DATALENGTH(AuthMethod)=15 AND CredentialId IS NOT NULL)),
 CONSTRAINT CK_AiCimdFamilyV1_Code CHECK(DeniedAt IS NULL AND CodeExpiresAt>CodeIssuedAt AND CodeExpiresAt<=DATEADD(second,60,CodeIssuedAt) AND ConsumedAt>=CodeIssuedAt AND ConsumedAt<CodeExpiresAt),
 CONSTRAINT CK_AiCimdFamilyV1_Pkce CHECK(DATALENGTH(Challenge)=43 AND Challenge NOT LIKE '%[^A-Za-z0-9_-]%' COLLATE Latin1_General_100_BIN2),
 CONSTRAINT CK_AiCimdFamilyV1_Identity CHECK(DATALENGTH(ExternalClientId) BETWEEN 4 AND 4096 AND LEN(ClientId)>0 AND LEN(RedirectUri)>0)
);
CREATE TABLE dbo.AiCimdProofControlV1(Id tinyint NOT NULL PRIMARY KEY CHECK(Id=1), Enabled bit NOT NULL DEFAULT 0);
INSERT dbo.AiCimdProofControlV1(Id,Enabled) VALUES(1,0);

CREATE TABLE dbo.AiCimdCredentialV1(
 Id bigint IDENTITY CONSTRAINT C4a_PK_AiOAuthCredential PRIMARY KEY, ShaleClientId int NOT NULL, IntegrationId uniqueidentifier NOT NULL, UserId int NOT NULL,
 GrantId uniqueidentifier NOT NULL, SessionId uniqueidentifier NOT NULL,
 CredentialHash binary(32) NOT NULL CONSTRAINT C4a_UQ_AiOAuthCredential_01 UNIQUE, Kind varchar(8) NOT NULL CONSTRAINT C4a_CK_AiOAuthCredential_01 CHECK(Kind IN('ACCESS','REFRESH')),
 ScopeMask tinyint NOT NULL CONSTRAINT C4a_CK_AiOAuthCredential_02 CHECK(ScopeMask BETWEEN 1 AND 3), Generation int NOT NULL CONSTRAINT C4a_CK_AiOAuthCredential_03 CHECK(Generation>=0),
 IssuedAt datetime2(7) NOT NULL CONSTRAINT C4a_DF_AiOAuthCredential_01 DEFAULT(SYSUTCDATETIME()), ExpiresAt datetime2(7) NOT NULL,
 ConsumedAt datetime2(7) NULL, RevokedAt datetime2(7) NULL,
 CONSTRAINT C4a_CK_AiOAuthCredential_04 CHECK(ExpiresAt>IssuedAt AND ExpiresAt<=DATEADD(hour,24,IssuedAt)),
 CONSTRAINT C4a_CK_AiOAuthCredential_05 CHECK(Kind<>'ACCESS' OR ExpiresAt<=DATEADD(minute,5,IssuedAt)),
 CONSTRAINT C4a_FK_AiOAuthCredential_01 FOREIGN KEY(ShaleClientId,SessionId,GrantId,IntegrationId,UserId) REFERENCES dbo.AiCimdFamilyV1(ShaleClientId,SessionId,GrantId,IntegrationId,UserId)
);
CREATE UNIQUE INDEX C4a_CredentialOwner ON dbo.AiCimdCredentialV1(ShaleClientId,Id,SessionId,GrantId,IntegrationId,UserId);
CREATE TABLE dbo.AiCimdInvocationV1(
 InvocationId uniqueidentifier NOT NULL PRIMARY KEY, CorrelationId uniqueidentifier NOT NULL,
 ShaleClientId int NOT NULL,UserId int NOT NULL,IntegrationId uniqueidentifier NOT NULL,GrantId uniqueidentifier NOT NULL,SessionId uniqueidentifier NOT NULL,AccessCredentialId bigint NOT NULL,
 ClientId varchar(64) COLLATE Latin1_General_100_BIN2 NOT NULL,KeyId uniqueidentifier NULL,
 Issuer nvarchar(256) COLLATE Latin1_General_100_BIN2 NOT NULL,Resource nvarchar(256) COLLATE Latin1_General_100_BIN2 NOT NULL,
 ScopeMask tinyint NOT NULL CHECK(ScopeMask BETWEEN 1 AND 3),CapabilityRevision bigint NOT NULL,PolicyRevision bigint NOT NULL,IntegrationRevision bigint NOT NULL,GrantRevision bigint NOT NULL,
 AdmittedAt datetime2(7) NOT NULL,DeadlineUtc datetime2(7) NOT NULL,HistoricalOnly bit NOT NULL,
 Operation tinyint NULL CHECK(Operation IN(1,2)),SearchPage int NULL CHECK(SearchPage BETWEEN 0 AND 9),RequestedCaseId int NULL CHECK(RequestedCaseId>0),
 DispatchClaimed bit NOT NULL DEFAULT(0),ReadFailed bit NOT NULL DEFAULT(0),ReadEventId bigint NULL,HandoffConsumed bit NOT NULL DEFAULT(0),
 FOREIGN KEY(ShaleClientId,UserId) REFERENCES dbo.Users(ShaleClientId,id),
 FOREIGN KEY(ShaleClientId,SessionId,GrantId,IntegrationId,UserId) REFERENCES dbo.AiDelegatedSession(ShaleClientId,SessionId,GrantId,IntegrationId,UserId),
 FOREIGN KEY(ShaleClientId,AccessCredentialId,SessionId,GrantId,IntegrationId,UserId) REFERENCES dbo.AiCimdCredentialV1(ShaleClientId,Id,SessionId,GrantId,IntegrationId,UserId),
 FOREIGN KEY(ShaleClientId,ReadEventId) REFERENCES dbo.IntegrationAccessAuditLog(ShaleClientId,Id)
);
CREATE INDEX C4a_InvocationOwner ON dbo.AiCimdInvocationV1(ShaleClientId,UserId,AdmittedAt);
CREATE TABLE dbo.AiCimdProofReceiptV1(Id tinyint NOT NULL PRIMARY KEY CHECK(Id=1),SourceHash binary(32) NOT NULL,BeforeHash binary(32) NOT NULL,CatalogHash binary(32) NOT NULL);
EXEC sys.sp_executesql N'ALTER SECURITY POLICY sec.TenantFilter ADD FILTER PREDICATE sec.fn_FilterByTenant(ShaleClientId) ON dbo.AiCimdFamilyV1, ADD BLOCK PREDICATE sec.fn_FilterByTenant(ShaleClientId) ON dbo.AiCimdFamilyV1 AFTER INSERT, ADD BLOCK PREDICATE sec.fn_FilterByTenant(ShaleClientId) ON dbo.AiCimdFamilyV1 AFTER UPDATE;';
EXEC sys.sp_executesql N'ALTER SECURITY POLICY sec.TenantFilter ADD FILTER PREDICATE sec.fn_FilterByTenant(ShaleClientId) ON dbo.AiCimdCredentialV1, ADD BLOCK PREDICATE sec.fn_FilterByTenant(ShaleClientId) ON dbo.AiCimdCredentialV1 AFTER INSERT, ADD BLOCK PREDICATE sec.fn_FilterByTenant(ShaleClientId) ON dbo.AiCimdCredentialV1 AFTER UPDATE;';
EXEC sys.sp_executesql N'ALTER SECURITY POLICY sec.TenantFilter ADD FILTER PREDICATE sec.fn_FilterByTenant(ShaleClientId) ON dbo.AiCimdInvocationV1, ADD BLOCK PREDICATE sec.fn_FilterByTenant(ShaleClientId) ON dbo.AiCimdInvocationV1 AFTER INSERT, ADD BLOCK PREDICATE sec.fn_FilterByTenant(ShaleClientId) ON dbo.AiCimdInvocationV1 AFTER UPDATE;';
CREATE ROLE AiCimdCaseRuntimeV1 AUTHORIZATION dbo;
CREATE ROLE AiCimdLifecycleV1 AUTHORIZATION dbo;
DECLARE @C4aModule0 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule0;
DECLARE @C4aModule1 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule1;
DECLARE @C4aModule2 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule2;
DECLARE @C4aModule3 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule3;
DECLARE @C4aModule4 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule4;
DECLARE @C4aModule5 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule5;
DECLARE @C4aModule6 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule6;
DECLARE @C4aModule7 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule7;
DECLARE @C4aModule8 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule8;
DECLARE @C4aModule9 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule9;
DECLARE @C4aModule10 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule10;
DECLARE @C4aModule11 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule11;
DECLARE @C4aModule12 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule12;
DECLARE @C4aModule13 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule13;
DECLARE @C4aModule14 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule14;
DECLARE @C4aModule15 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aModule15;
GRANT EXECUTE ON dbo.AiCimdDataAuthenticateV1 TO AiCimdCaseRuntimeV1;
GRANT EXECUTE ON dbo.AiCimdDataSearchCasesV1 TO AiCimdCaseRuntimeV1;
GRANT EXECUTE ON dbo.AiCimdDataGetCaseOverviewV1 TO AiCimdCaseRuntimeV1;
GRANT EXECUTE ON dbo.AiCimdDataFinishCaseQuotaV1 TO AiCimdCaseRuntimeV1;
GRANT EXECUTE ON dbo.AiCimdDataAuthorizeCaseHandoffV1 TO AiCimdCaseRuntimeV1;
GRANT EXECUTE ON dbo.AiCimdDataRecordCaseFailureV1 TO AiCimdCaseRuntimeV1;
GRANT EXECUTE ON dbo.AiCimdRevokeFamilyV1 TO AiCimdLifecycleV1;
DENY SELECT,INSERT,UPDATE,DELETE,ALTER,CONTROL ON dbo.AiCimdFamilyV1 TO AiCimdCaseRuntimeV1;
DENY SELECT,INSERT,UPDATE,DELETE,ALTER,CONTROL ON dbo.AiCimdCredentialV1 TO AiCimdCaseRuntimeV1;
DENY SELECT,INSERT,UPDATE,DELETE,ALTER,CONTROL ON dbo.AiCimdInvocationV1 TO AiCimdCaseRuntimeV1;
DENY SELECT,INSERT,UPDATE,DELETE,ALTER,CONTROL ON dbo.AiCimdProofControlV1 TO AiCimdCaseRuntimeV1;
DENY SELECT,INSERT,UPDATE,DELETE,ALTER,CONTROL ON dbo.AiCimdProofReceiptV1 TO AiCimdCaseRuntimeV1;
DENY SELECT,INSERT,UPDATE,DELETE,ALTER,CONTROL ON dbo.AiCimdFamilyV1 TO AiCimdLifecycleV1;
DENY SELECT,INSERT,UPDATE,DELETE,ALTER,CONTROL ON dbo.AiCimdCredentialV1 TO AiCimdLifecycleV1;
DENY SELECT,INSERT,UPDATE,DELETE,ALTER,CONTROL ON dbo.AiCimdInvocationV1 TO AiCimdLifecycleV1;
DENY SELECT,INSERT,UPDATE,DELETE,ALTER,CONTROL ON dbo.AiCimdProofControlV1 TO AiCimdLifecycleV1;
DENY SELECT,INSERT,UPDATE,DELETE,ALTER,CONTROL ON dbo.AiCimdProofReceiptV1 TO AiCimdLifecycleV1;
DENY EXECUTE ON dbo.AiCimdDataLocateAccessOwnerV1 TO public;
DENY EXECUTE ON dbo.AiCimdDataLoadAuthorityV1 TO public;
DENY EXECUTE ON dbo.AiCimdDataAppendAccessV1 TO public;
DENY EXECUTE ON dbo.AiCimdDataAdmitV1 TO public;
DECLARE @C4aModules table(Name sysname PRIMARY KEY,Hash binary(32),OwnerLookup bit); INSERT @C4aModules VALUES (N'AiCimdDataLocateAccessOwnerV1',0x6c358f5c58362a3ca79303ae4bc4296f4772349216743862be3fa17a36f3b67f,1),(N'AiCimdDataLoadAuthorityV1',0x8e3907c529e7a9c9241c1cc5a47b0812b004856e87ee3bef71f1869852b82bc7,0),(N'AiCimdDataAuthenticateV1',0x5da2096e5f92f54033fc058b2fd710e7fe72f2c8b883f7b6e0ed64096c5fbe36,0),(N'AiCimdDataAppendAccessV1',0x8cbdbb3e875d2757571f3c2db4d64289cc0805742cf51b09296e20b88b265333,0),(N'AiCimdDataAdmitV1',0x3a8f1f250bbfaf5981ab7373dbeef07fe8162f58cb65162737ab88fc0434872e,0),(N'AiCimdDataSearchCasesV1',0x142505fa5fd4c3fb9574afa670af2303e8192b3d0dac9f3657b2eb4935661cf3,0),(N'AiCimdDataGetCaseOverviewV1',0xb99848d7a8e2b8ae75635cea0b02067ba42cbae7def13916fc9813c0bdf1013f,0),(N'AiCimdDataFinishCaseQuotaV1',0xb40ceade881d455d4b399d3a254737ced92379adf25f7ef0024621b7e9c4b868,0),(N'AiCimdDataAuthorizeCaseHandoffV1',0xe31f7b3de78a951d6115057543b764ab2f881dbd8747165f0bc4432b355afd6e,0),(N'AiCimdDataRecordCaseFailureV1',0xc36fe5be62a5f47dbdd707200b9c8ff19ceaf5ea006952a347be59b052fabef8,0),(N'AiCimdDataImmutableInvocation',0xf8be9680b7baae5b780d1d9af85bddc215596bca774531e441bc41aa0640f52b,0),(N'AiCimdImmutableFamilyV1',0x6f57d0cd6f0942cd7d577b212e27f6e4e2008dae87f0e816c9dfe04b8181d852,0),(N'AiCimdImmutableCredentialV1',0x21443ac7c353dd83327a690260162835b770d232c11cfbacd0ada397012ac808,0),(N'AiCimdLifecycle_CredentialV1',0x10c80b55f931b54600a032593ebe674ad3e6758062a75b2e991b0abff62eeedd,0),(N'AiCimdRevokeFamilyV1',0xb2c491da48cbf8f7099aa1e488aa89d3275369610817a4e6f6d4aabc179f2b27,0),(N'AiCimdImmutableReceiptV1',0xa0bf04f6e6687307d15c46292d3b9102dedb264b37c986a797430ec1a25119ff,0);
IF EXISTS(SELECT 1 FROM @C4aModules e WHERE NOT EXISTS(SELECT 1 FROM sys.objects o JOIN sys.schemas s ON s.schema_id=o.schema_id JOIN sys.sql_modules m ON m.object_id=o.object_id WHERE s.name='dbo' AND o.name=e.Name AND COALESCE(o.principal_id,s.principal_id)=1 AND m.uses_ansi_nulls=1 AND m.uses_quoted_identifier=1 AND ((e.OwnerLookup=1 AND m.execute_as_principal_id=-2) OR (e.OwnerLookup=0 AND m.execute_as_principal_id IS NULL)) AND HASHBYTES('SHA2_256',m.definition)=e.Hash)) THROW 59400,'CIMD proof module source/owner/context drift.',1;
IF EXISTS(SELECT 1 FROM sys.objects o JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE s.name='dbo' AND o.name IN(SELECT Name FROM @C4aObjects) AND COALESCE(o.principal_id,s.principal_id)<>1)
 THROW 59400,'CIMD object ownership drift.',1;
IF EXISTS(SELECT 1 FROM sys.triggers t WHERE OBJECT_NAME(t.parent_id) IN(SELECT Name FROM @C4aObjects) AND t.name NOT IN(SELECT Name FROM @C4aModules))
 OR EXISTS(SELECT 1 FROM sys.sql_expression_dependencies d JOIN sys.objects o ON o.object_id=d.referencing_id WHERE (o.name IN(SELECT Name FROM @C4aObjects) AND o.type='U' OR o.type IN('C','D') AND OBJECT_NAME(o.parent_object_id) IN(SELECT Name FROM @C4aObjects)) AND (d.referenced_server_name IS NOT NULL OR d.referenced_database_name IS NOT NULL OR EXISTS(SELECT 1 FROM sys.objects f WHERE f.object_id=d.referenced_id AND f.type IN('FN','IF','TF','FS','FT','P','PC','SN'))))
 THROW 59400,'Unreviewed CIMD trigger/table-expression edge.',1;
IF (SELECT COUNT(*) FROM sys.security_predicates p JOIN sys.security_policies sp ON sp.object_id=p.object_id WHERE OBJECT_NAME(p.target_object_id) IN('AiCimdFamilyV1','AiCimdCredentialV1','AiCimdInvocationV1') AND sp.object_id=OBJECT_ID('sec.TenantFilter') AND sp.is_enabled=1 AND sp.is_schema_bound=1 AND p.predicate_definition COLLATE Latin1_General_100_BIN2=N'([sec].[fn_FilterByTenant]([ShaleClientId]))')<>9
 OR (SELECT COUNT(*) FROM sys.security_predicates WHERE OBJECT_NAME(target_object_id) IN('AiCimdFamilyV1','AiCimdCredentialV1','AiCimdInvocationV1'))<>9
 THROW 59400,'CIMD strict RLS drift.',1;
DECLARE @C4aPermissions table(RoleName sysname COLLATE Latin1_General_100_BIN2,ObjectName sysname COLLATE Latin1_General_100_BIN2,PermissionName sysname COLLATE Latin1_General_100_BIN2,State char(1) COLLATE Latin1_General_100_BIN2); INSERT @C4aPermissions VALUES (N'AiCimdCaseRuntimeV1',N'AiCimdFamilyV1',N'SELECT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdFamilyV1',N'INSERT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdFamilyV1',N'UPDATE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdFamilyV1',N'DELETE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdFamilyV1',N'ALTER',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdFamilyV1',N'CONTROL',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdCredentialV1',N'SELECT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdCredentialV1',N'INSERT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdCredentialV1',N'UPDATE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdCredentialV1',N'DELETE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdCredentialV1',N'ALTER',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdCredentialV1',N'CONTROL',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdInvocationV1',N'SELECT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdInvocationV1',N'INSERT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdInvocationV1',N'UPDATE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdInvocationV1',N'DELETE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdInvocationV1',N'ALTER',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdInvocationV1',N'CONTROL',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofControlV1',N'SELECT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofControlV1',N'INSERT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofControlV1',N'UPDATE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofControlV1',N'DELETE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofControlV1',N'ALTER',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofControlV1',N'CONTROL',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofReceiptV1',N'SELECT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofReceiptV1',N'INSERT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofReceiptV1',N'UPDATE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofReceiptV1',N'DELETE',N'D'),(N'Ai